export function createResilientFetch({
  fetch,
  sleep,
  random = Math.random,
  maxAttempts = 4,
  baseDelayMs = 200,
  maxDelayMs = 5000,
}) {
  const retryableStatuses = new Set([408, 429, 500, 502, 503, 504]);
  const retryableMethods = new Set(["GET", "HEAD", "OPTIONS", "PUT", "DELETE"]);

  return async function rfetch(url, options = {}) {
    const requestedMethod = options.method;
    const method =
      requestedMethod === undefined
        ? "GET"
        : String(requestedMethod).toUpperCase();

    let canRetry = retryableMethods.has(method);

    if (method === "POST" || method === "PATCH") {
      const headers = options.headers;
      if (headers != null) {
        canRetry =
          typeof headers.get === "function"
            ? headers.get("Idempotency-Key") != null
            : Object.keys(headers).some(
                (name) => name.toLowerCase() === "idempotency-key",
              );
      }
    }

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      if (options.signal?.aborted) {
        const error = new Error("The operation was aborted.");
        error.name = "AbortError";
        throw error;
      }

      let response;
      let networkFailure = false;

      try {
        response = await fetch(url, options);
      } catch (error) {
        if (
          error?.name === "AbortError" ||
          !canRetry ||
          attempt >= maxAttempts
        ) {
          throw error;
        }
        networkFailure = true;
      }

      let delayMs;

      if (!networkFailure) {
        if (
          response.ok === true ||
          !canRetry ||
          !retryableStatuses.has(response.status) ||
          attempt >= maxAttempts
        ) {
          return response;
        }

        const retryAfter = response.headers.get("Retry-After");
        if (
          typeof retryAfter === "string" &&
          retryAfter.length > 0 &&
          !/[^0-9]/.test(retryAfter)
        ) {
          delayMs = Number(retryAfter) * 1000;
          if (delayMs > maxDelayMs) {
            return response;
          }
        }
      }

      if (delayMs === undefined) {
        delayMs = Math.floor(
          random() *
            Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1)),
        );
      }

      await sleep(delayMs, options.signal);
    }
  };
}
